PLAN_NO = #{planNo}, PLAN_NAME = #{planName}, PLAN_TYPE = #{planType}, PLAN_YEAR = #{planYear}, PLAN_QUARTER = #{planQuarter}, PLAN_MONTH = #{planMonth}, FINANCING_TARGET = #{financingTarget}, ACTUAL_AMOUNT = #{actualAmount}, COMPLETION_RATE = #{completionRate}, PLAN_STATUS = #{planStatus}, APPROVAL_BY = #{approvalBy}, APPROVAL_TIME = #{approvalTime}, APPROVAL_OPINION = #{approvalOpinion}, PLAN_START_DATE = #{planStartDate}, PLAN_END_DATE = #{planEndDate}, CURRENCY = #{currency}, DEPARTMENT = #{department}, OPERATOR = #{operator}, REMARK = #{remark}, UPDATE_TIME = #{updateTime}, UPDATE_BY = #{updateBy},
